TEXT ·nativeCallDispatch(SB), NOSPLIT|NOFRAME, $0-0
    SUBQ $24, SP                  // align the stack and preserve the frame pointer
    MOVQ DI, 16(SP)
    MOVQ 0(DI), R10
    MOVQ 16(SP), R11
    MOVQ 8(R11), DI
    MOVQ 16(R11), SI
    MOVQ 24(R11), DX
    MOVQ 32(R11), CX
    MOVQ 40(R11), R8
    MOVQ 48(R11), R9
    CALL R10
    MOVQ 16(SP), DI
    MOVQ AX, 56(DI)
    ADDQ $24, SP
    XORL AX, AX                   // return zero from the C wrapper
    RET
